"""Automation Agent orchestration guards. Anti-Hang semantics are not implemented here."""

def task_memory_gate(*, substantive=True, long_or_complex=False, workspace_bound=False):
    if not substantive:
        return "NO_TEMP_WORKSPACE"
    if long_or_complex and not workspace_bound:
        return "CREATE_TEMP_TASK"
    return "TASK_MEMORY_GATE"

def owner_gate(*, substantive=True, owner=None, knowledge_or_reasoning=False):
    if not substantive:
        return {"verdict":"ROOT_GLUE_ONLY"}
    if owner:
        return {"verdict":"DELEGATE_REQUIRED","owner":owner}
    if knowledge_or_reasoning:
        return {"verdict":"DELEGATE_REQUIRED","owner":"TRUE_RESEARCH"}
    return {"verdict":"OWNER_RESOLUTION_REQUIRED"}

def local_closure_gate(*, substantive=True, helper_invoked=False, critic_required=False, critic_passed=False):
    if not substantive:
        return "NO_SUBSTANTIVE_GATE"
    if not helper_invoked:
        return "INVOKE_OWNED_HELPER"
    if critic_required and not critic_passed:
        return "INVOKE_CRITIC_OR_ACCEPTANCE"
    return "ALLOW_OWNER_RETURN"

def temp_cleanup_gate(*, temp_workspace_exists=False, cleanup_verified=False):
    if temp_workspace_exists and not cleanup_verified:
        return "INVOKE_TRUE_MEMORY_INQUISITOR_CLEANUP"
    return "ALLOW_COMPLETION_EVALUATION"

def global_reentry(*, unresolved_material_frontier=False, callable_owner_exists=False):
    if unresolved_material_frontier:
        return "DELEGATE_REQUIRED" if callable_owner_exists else "RECOVER_OWNER_ROUTE"
    return "REASSESS_GLOBAL_FRONTIERS"

ANTI_HANG_REQUIRED_HOOKS = {
    "TASK_ENTRY",
    "BEFORE_ACTION",
    "AFTER_ACTION",
    "AFTER_MATERIAL_RETURN",
    "PRESSURE",
    "BEFORE_USER_RETURN",
    "USER_STOP",
}

def anti_hang_hook_required(event):
    return str(event or "").upper() in ANTI_HANG_REQUIRED_HOOKS

def _trace_record(item):
    if isinstance(item, dict):
        return {
            "event": str(item.get("event") or "").upper(),
            "action_id": item.get("action_id"),
            "effect_id": item.get("effect_id"),
        }
    return {"event": str(item or "").upper(), "action_id": None, "effect_id": None}

def anti_hang_hook_trace_gate(
    trace_events,
    *,
    external_action_opened=False,
    external_action_count=None,
    material_return_observed=False,
    material_return_count=None,
    user_return_attempted=False,
    explicit_user_stop=False,
    pressure_observed=False,
    pressure_count=None,
):
    """Verify mandatory hook coverage, ordering and multiplicity for a bounded trace."""
    trace = [_trace_record(item) for item in (trace_events or [])]
    events = [item["event"] for item in trace]
    missing = []
    issues = []

    if not events or events[0] != "TASK_ENTRY":
        missing.append("TASK_ENTRY")
    elif events.count("TASK_ENTRY") != 1:
        issues.append("TASK_ENTRY_MUST_OCCUR_EXACTLY_ONCE_AT_TRACE_START")

    open_action = None
    before_count = 0
    after_count = 0
    stop_index = None

    for index, item in enumerate(trace):
        event = item["event"]
        if event == "USER_STOP" and stop_index is None:
            stop_index = index
        if stop_index is not None and index > stop_index and event not in {"BEFORE_USER_RETURN"}:
            issues.append("NO_HOOKS_AFTER_USER_STOP_EXCEPT_BEFORE_USER_RETURN")

        if event == "BEFORE_ACTION":
            before_count += 1
            if item.get("action_id") is None:
                issues.append("ACTION_ID_REQUIRED")
            if open_action is not None:
                issues.append("NESTED_OR_UNCLOSED_BEFORE_ACTION")
            open_action = item
        elif event == "AFTER_ACTION":
            after_count += 1
            if item.get("action_id") is None:
                issues.append("ACTION_ID_REQUIRED")
            if open_action is None:
                issues.append("AFTER_ACTION_WITHOUT_PRECEDING_BEFORE_ACTION")
                continue
            before_id = open_action.get("action_id")
            after_id = item.get("action_id")
            if before_id != after_id:
                issues.append("ACTION_ID_MISMATCH")
            open_action = None

    if open_action is not None:
        issues.append("BEFORE_ACTION_WITHOUT_MATCHING_AFTER_ACTION")
    if before_count != after_count:
        issues.append("BEFORE_AFTER_ACTION_COUNT_MISMATCH")

    observed_action_count = before_count if before_count == after_count else min(before_count, after_count)
    if external_action_opened and external_action_count is None:
        issues.append("EXTERNAL_ACTION_COUNT_REQUIRED")
    if external_action_opened and observed_action_count < 1:
        missing.extend(["BEFORE_ACTION", "AFTER_ACTION"])
    if external_action_count is not None and observed_action_count != int(external_action_count):
        issues.append("EXTERNAL_ACTION_COUNT_MISMATCH")

    observed_material_returns = events.count("AFTER_MATERIAL_RETURN")
    if material_return_observed and material_return_count is None:
        issues.append("MATERIAL_RETURN_COUNT_REQUIRED")
    if material_return_observed and observed_material_returns < 1:
        missing.append("AFTER_MATERIAL_RETURN")
    if material_return_count is not None and observed_material_returns != int(material_return_count):
        issues.append("MATERIAL_RETURN_COUNT_MISMATCH")

    observed_pressure = events.count("PRESSURE")
    if pressure_observed and pressure_count is None:
        issues.append("PRESSURE_COUNT_REQUIRED")
    if pressure_observed and observed_pressure < 1:
        missing.append("PRESSURE")
    if pressure_count is not None and observed_pressure != int(pressure_count):
        issues.append("PRESSURE_COUNT_MISMATCH")

    if explicit_user_stop and "USER_STOP" not in events:
        missing.append("USER_STOP")
    if explicit_user_stop and events.count("USER_STOP") != 1:
        issues.append("USER_STOP_MUST_OCCUR_EXACTLY_ONCE")

    if user_return_attempted:
        if "BEFORE_USER_RETURN" not in events:
            missing.append("BEFORE_USER_RETURN")
        elif events.count("BEFORE_USER_RETURN") != 1:
            issues.append("BEFORE_USER_RETURN_MUST_OCCUR_EXACTLY_ONCE")
        elif events[-1] != "BEFORE_USER_RETURN":
            issues.append("BEFORE_USER_RETURN_MUST_BE_FINAL_HOOK")

    missing = sorted(set(missing))
    issues = sorted(set(issues))
    if missing:
        return {
            "verdict": "ANTI_HANG_HOOK_COVERAGE_MISSING",
            "missing": missing,
            "issues": issues,
            "observed_action_count": observed_action_count,
        }
    if issues:
        return {
            "verdict": "ANTI_HANG_HOOK_TRACE_INVALID",
            "missing": [],
            "issues": issues,
            "observed_action_count": observed_action_count,
        }
    return {
        "verdict": "ANTI_HANG_HOOK_COVERAGE_PASS",
        "missing": [],
        "issues": [],
        "observed_action_count": observed_action_count,
    }

def anti_hang_global_return_coverage_gate(trace_events, **observations):
    """Whole-task return is forbidden until all applicable Anti-Hang hooks form a valid trace."""
    result = anti_hang_hook_trace_gate(
        trace_events,
        user_return_attempted=True,
        **observations,
    )
    if result["verdict"] != "ANTI_HANG_HOOK_COVERAGE_PASS":
        return {
            "verdict": "AUTO_CONTINUE_REPAIR_HOOK_COVERAGE",
            "missing": result.get("missing", []),
            "issues": result.get("issues", []),
            "user_visible_return_allowed": False,
        }
    return {
        "verdict": "ALLOW_ANTI_HANG_RETURN_EVALUATION",
        "missing": [],
        "issues": [],
        "user_visible_return_allowed": True,
    }
